{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "Piritrexim, a lipophilic 2,4-diaminopyrimidine antifolate, has approximately 75% oral bioavailability in patients; the query shares the 2,4-diaminopyrimidine and methoxyaryl motifs, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Trimazosin, an aminoquinazoline with a trimethoxyaryl group, showed 63% oral bioavailability in healthy men; the query contains related aminoazine and methoxyaryl features, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Alfuzosin, an aminoquinazoline with methoxy substituents, has a mean absolute oral bioavailability of 64.5% in healthy subjects; this supports the transferability of high F to the query's aminoazine/methoxyaryl scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Abecarnil, an indole-containing drug, has absolute oral bioavailability ranging from 29% to 96% in young healthy subjects; the query contains a chloroindole carboxamide, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C51"],
      "claim": "Betrixaban, a chloroaromatic/amidine oral anticoagulant, has 47% absolute oral bioavailability in humans; the query shares chloroaromatic and amide/heteroaromatic features, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Alisertib, a complex aromatic kinase inhibitor with chloro, methoxy, and amide motifs, showed a bioavailability of 0.671 in a pediatric model; this supports that complex molecules similar to the query can achieve F >= 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Multiple structurally related molecules with shared 2,4-diaminopyrimidine, aminoquinazoline, methoxyheteroaromatic, and chloroindole motifs consistently show absolute oral bioavailability of 34-95%, supporting F >= 20%. The physicochemical prior is uncertain and is outweighed by transferable human PK evidence, though the query's higher MW and TPSA introduce residual uncertainty.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement exists for the query molecule.",
    "Most supportive analogs have lower molecular weight and TPSA than the query; the query's high TPSA (145.5) and MW (535) may reduce absorption and are not fully covered by the analogs.",
    "First-pass metabolism and solubility/dissolution behavior of the query are unknown."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

